"""Regenerate requirements.txt from uv.lock.

    uv run python scripts/export_requirements.py

``uv export`` pins the platform-specific PyTorch builds (``+cu126`` on Windows, ``+cpu``
on Linux) but does not record which index they come from, so pip could not find them.
This script adds the index lines.
"""

from __future__ import annotations

import subprocess
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent
OUTPUT = REPO_ROOT / "requirements.txt"
HEADER = """\
# Generated by scripts/export_requirements.py from uv.lock - do not edit by hand.
# Install with:  pip install -r requirements.txt
# The extra indexes provide the PyTorch builds: +cu126 for Windows, +cpu for Linux.
--extra-index-url https://download.pytorch.org/whl/cu126
--extra-index-url https://download.pytorch.org/whl/cpu
"""


def main() -> None:
    exported = subprocess.run(
        [
            "uv",
            "export",
            "--format",
            "requirements-txt",
            "--no-hashes",
            "--no-emit-project",
            "--no-dev",
            "--no-header",
        ],
        cwd=REPO_ROOT,
        check=True,
        capture_output=True,
        text=True,
    ).stdout
    OUTPUT.write_text(HEADER + exported, encoding="utf-8", newline="\n")
    print(f"wrote {OUTPUT.relative_to(REPO_ROOT)}")


if __name__ == "__main__":
    main()
